var MSSCustodyBulkProcessUtils_workspace = Class.create();
MSSCustodyBulkProcessUtils_workspace.prototype = {
    initialize: function() {},
    createBulkCaseTask: function(sysparm_query, bulk_id, sysparm_outcome, sysparm_tradeCount) { //MSSOTIQUBE-2464
        try {

            //var query = this.getParameter('sysparm_query'),
            //bulkId = this.getParameter('bulk_id'),
            //tskoutcome = this.getParameter("sysparm_outcome"),
            var query = sysparm_query;
            var bulkId = bulk_id;
            var tskoutcome = sysparm_outcome;
            var parm1 = bulkId + '|' + tskoutcome;
            //tradeCount = this.getParameter("sysparm_tradeCount"),
            var tradeCount = sysparm_tradeCount;
            var threshold = gs.getProperty('x_hsb11_mss_c_proc.bulk_threshold_event_queue');

            var grCustodyTrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            grCustodyTrade.addEncodedQuery(query);
            grCustodyTrade.query();

            if (parseInt(tradeCount, 10) > parseInt(threshold, 10) && gs.getProperty('x_hsb11_mss_c_proc.BulkEventQueue') == 'true') {
                //If number of trades in the bulk is larger than threshold, use asyn event queue approach
                var tradesArray = [],
                    i = 0,
                    tradesInSingleEvt = gs.getProperty('x_hsb11_mss_c_proc.number_of_items_in_bulk_event'); //number of trades to be processed via a single event for case creation

                while (grCustodyTrade.next()) {
                    tradesArray.push(grCustodyTrade.sys_id.toString());
                    i++;
                    if (i == tradesInSingleEvt) {
                        gs.eventQueue("x_hsb11_mss_c_proc.cust_mmbulk_casecreat", current, parm1, tradesArray.join(','));
                        //reset to initial
                        i = 0;
                        tradesArray = [];
                    }
                }

                //create event for the remainings after loop completes
                if (i > 0) {
                    gs.eventQueue("x_hsb11_mss_c_proc.cust_mmbulk_casecreat", current, parm1, tradesArray.join(','));
                }

            } else {

                //for small bulk, process in sequential right away
                while (grCustodyTrade.next()) {
                    var grcustodycase = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_case");
                    grcustodycase.initialize();
                    grcustodycase.short_description = 'Manually triggered by Bulk processing';
                    grcustodycase.description = 'Manually triggered by Bulk processing';
                    grcustodycase.trade_id = grCustodyTrade.sys_id;
                    grcustodycase.bulk_id = bulkId;
                    grcustodycase.triggered_by = '19c79fbb1ba30a10c6ada6c7b04bcbd5';
                    grcustodycase.case_status = 'ec34a3731b270a10c6ada6c7b04bcb7a';
                    if (tskoutcome == 'Amend Trade') { // fix for 7211- duplicate makers getting created (one from flow and oher from script)
                        grcustodycase.amend_case = 'True';
                    }
                    grcustodycase.insert();

                    //Create Maker Task as part of Amend
                    if (tskoutcome == 'Amend Trade') {
                        //var flowAPI = new sn_fd.FlowAPI();
                        //var subflowSysId = '2b992c1e1bdcaa506ed00e1ad34bcbed';
                        // var subflowName = 'x_hsb11_mss_c_proc.hsbccustodytrade_amend_maker'; // changes to fix 7211
                        // var inputs = {};
                        // inputs.re_initiate_process = false;
                        // inputs.case_id = grcustodycase;
                        // // sn_fd.FlowAPI.getRunner().subflow(subflowName).inBackground().withInputs(inputs).run();
                        // new global.amendTaskCreation().createAmendMakerTask(subflowName,inputs);

                        // if (!result) {
                        //     gs.error('Failed to start subflow');
                        // }
                        try {
                            // changes to fix 7211
                            var amendTemplate = new global.JSON.parse(this.selectTaskTemplate('CUSTODYTTMP00126')); //Template selection
                            var grcustodytask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
                            grcustodytask.initialize();
                            grcustodytask.trade_task_type = 'Maker';
                            grcustodytask.short_description = amendTemplate.shortDescription; //deparsed from method selectTaskTemplate
                            grcustodytask.description = amendTemplate.description; //deparsed from method selectTaskTemplate
                            grcustodytask.trade_task_type = amendTemplate.trdTaskType;
                            grcustodytask.trade_task_template_id = amendTemplate.templateID;
                            grcustodytask.trade_id = grCustodyTrade.sys_id;
                            grcustodytask.trade_case_id = grcustodycase.sys_id;
                            grcustodytask.bulk_id = bulkId;
                            grcustodytask.outcome = 'Amend Trade';
                            grcustodytask.checker_decision = 'Amend';
                            grcustodytask.follow_up = new GlideDateTime();
                            grcustodytask.insert();

                        } catch (ex) {
                            gs.error('SI MSSCustodyBulkProcessUtils_workspace - Error while MM bulk case creation, bulkID amend trade:' + bulkId + ',error:' + ex.message);
                        }
                    }
                    grCustodyTrade.case_type = 'manual';
                    grCustodyTrade.update();
                }
            }

        } catch (ex) {
            gs.error('SI MSSCustodyBulkProcessUtils_workspace - Error while MM bulk case creation, bulkID:' + bulkId + ',error:' + ex.message);
        }
    },

    selectTaskTemplate: function(tempNum) {
        var taskTemplate = new GlideRecord('x_hsb11_mss_c_proc_custody_trade_task_template');
        taskTemplate.addQuery('template_id', tempNum);
        taskTemplate.query();
        if (taskTemplate.next()) {
            var tempContents = {
                "description": taskTemplate.getValue("template_description"),
                "shortDescription": taskTemplate.getValue("template_short_description"),
                "trdTaskType": taskTemplate.getValue('trade_task_type'),
                "templateID": taskTemplate.getValue('sys_id')
            };
            return JSON.stringify(tempContents);
        }

    },



    updateMakerTask: function(sysparm_bulkid, sysparm_assignmentgroup, sysparm_assignedto, sysparm_outcome, sysparm_advice, sysparm_reasoncode, sysparm_reasondescription, sysparm_suspend, sysparm_cancelby, sysparm_settlementtype, sysparm_bktobk, sysparm_cancellationreference, sysparm_collectcancelcharge, sysparm_settDate, sysparm_fxrTD, sysparm_valDate, sysparm_comments, sysparm_uploadType, sysparm_tasksCount, sysparm_fxcx, sysparm_gdi, sysparm_subOutcome, sysparm_transRef, sysparm_transType, sysparm_legStatus, sysparm_switchRef, sysparm_counterpartyCode) { //MSSCUSTODY-3396 //MSSOTIQUBE-2465

        try {
            /*var bulkid = this.getParameter('sysparm_bulkid');
            var assignmentgroup = this.getParameter('sysparm_assignmentgroup');
            var assignedto = this.getParameter('sysparm_assignedto');
            var outcome = this.getParameter('sysparm_outcome');
            var advice = this.getParameter('sysparm_advice');
            var reasoncode = this.getParameter('sysparm_reasoncode');
            var reasondesc = this.getParameter('sysparm_reasondescription');
            var suspend = this.getParameter('sysparm_suspend');
            var cancelby = this.getParameter('sysparm_cancelby');
            var setttype = this.getParameter('sysparm_settlementtype');
            var bktobkinfo = this.getParameter('sysparm_bktobk');
            var cancreference = this.getParameter('sysparm_cancellationreference');
            var cancelcharge = this.getParameter('sysparm_collectcancelcharge');
            //adding as part of 4901
            var settDate = this.getParameter('sysparm_settDate');
            var fxrTD = this.getParameter('sysparm_fxrTD');
            var valDate = this.getParameter('sysparm_valDate');
            var comments = this.getParameter('sysparm_comments'); // MSSCUSTODY-6379
            var uploadType = this.getParameter('sysparm_uploadType'); // MSSCUSTODY-6821 // 7191
            var tasksCount = this.getParameter('sysparm_tasksCount');

            //MSSCUSTODY-6087
            var fxcx = this.getParameter('sysparm_fxcx');
            var gdi = this.getParameter('sysparm_gdi');

            //MSSCUSTODY-7226
            var subOutcome = this.getParameter('sysparm_subOutcome');
            var transRef = this.getParameter('sysparm_transRef');
            var transType = this.getParameter('sysparm_transType');
            var legStatus = this.getParameter('sysparm_legStatus');
            var switchRef = this.getParameter('sysparm_switchRef');
            var counterpartyCode = this.getParameter('sysparm_counterpartyCode');
			*/

            var bulkid = sysparm_bulkid;
            var assignmentgroup = sysparm_assignmentgroup;
            var assignedto = sysparm_assignedto;
            var outcome = sysparm_outcome;
            var advice = sysparm_advice;
            var reasoncode = sysparm_reasoncode;
            var reasondesc = sysparm_reasondescription;
            var suspend = sysparm_suspend;
            var cancelby = sysparm_cancelby;
            var setttype = sysparm_settlementtype;
            var bktobkinfo = sysparm_bktobk;
            var cancreference = sysparm_cancellationreference;
            var cancelcharge = sysparm_collectcancelcharge;
            //adding as part of 4901
            var settDate = sysparm_settDate;
            var fxrTD = sysparm_fxrTD;
            var valDate = sysparm_valDate;
            var comments = sysparm_comments; // MSSCUSTODY-6379
            var uploadType = sysparm_uploadType; // MSSCUSTODY-6821 // 7191
            var tasksCount = sysparm_tasksCount;

            //MSSCUSTODY-6087
            var fxcx = sysparm_fxcx;
            var gdi = sysparm_gdi;

            //MSSCUSTODY-7226
            var subOutcome = sysparm_subOutcome;
            var transRef = sysparm_transRef;
            var transType = sysparm_transType;
            var legStatus = sysparm_legStatus;
            var switchRef = sysparm_switchRef;
            var counterpartyCode = sysparm_counterpartyCode;

            var makerTasks = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            makerTasks.addEncodedQuery('active=true^trade_task_type=Maker^bulk_id=' + bulkid);
            makerTasks.query();

            while (makerTasks.next()) {
                if (outcome == 'Review and closed the task') { // MSSCUSTODY-3964 - Cancelling associated flow if outcome is review and close the task for manual.
                    makerTasks.state = '3'; //closing related maker task
                    makerTasks.assignment_group = assignmentgroup; //Populating assignment group
                    makerTasks.assigned_to = assignedto; //Populating assigned to
                    makerTasks.outcome = outcome;
                    makerTasks.lock = false; //MSSCUSTODY-3993
                    makerTasks.update();
                    var grCusCase = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_case");
                    grCusCase.addEncodedQuery('sys_id=' + makerTasks.trade_case_id + '^bulk_id=' + bulkid);
                    grCusCase.query();
                    if (grCusCase.next()) {
                        grCusCase.state = '3';
                        grCusCase.update();
                    }

                    new x_hsb11_mss_c_proc.MSSCustodyBulkUtils().cancelFlow(makerTasks.trade_case_id, 'Cancelling flow as state is Review and Close');
                    makerTasks.work_notes = 'Cancelling flow as state is Review and Close'; // Updating work notes of Task
                } else {

                    makerTasks.assignment_group = assignmentgroup; //Populating assignment group
                    makerTasks.assigned_to = assignedto; //Populating assigned to
                    makerTasks.outcome = outcome;
                    makerTasks.advice = advice;
                    if ((uploadType == '') || (uploadType == 'bulk_level')) {
                        makerTasks.reason_code = reasoncode;
                        makerTasks.reason_description = reasondesc;
                        makerTasks.cancellation_reference = cancreference;
                    }
                    makerTasks.suspend = suspend;
                    makerTasks.cancel_by = cancelby; // for outcome 'Process Trade Cancellation'
                    makerTasks.settlement_type = setttype; // for outcome 'Settle Trade'
                    makerTasks.bk_to_bk_info = bktobkinfo;
                    makerTasks.collect_cancel_charge = cancelcharge;
                    makerTasks.state = '3'; //closing related maker task
                    makerTasks.lock = false; //MSSCUSTODY-3993

                    // MSSCUSTODY-6379
                    makerTasks.work_notes = comments;

                    //MSSCUSTODY-6087
                    makerTasks.fx_cx = fxcx;
                    makerTasks.gdi_indicator = gdi;

                    //MSSCUSTODY-7266
                    makerTasks.bulk_id.sub_outcome = subOutcome;
                    makerTasks.bulk_id.transaction_reference = transRef;
                    makerTasks.bulk_id.transaction_type_display = transType;
                    makerTasks.bulk_id.legacy_status_display = legStatus;
                    makerTasks.bulk_id.pair_switch_reference = switchRef;
                    makerTasks.bulk_id.amend_counterparty_code_ref = counterpartyCode;

                    //added as part of 4901
                    if ((makerTasks.trade_id.contract_type == 'C') && (outcome == 'Confirm Trade')) {
                        makerTasks.value_date = valDate;
                    } else if ((makerTasks.trade_id.contract_type != 'C') && (outcome == 'Confirm Trade')) {
                        makerTasks.value_date = "";
                    } else if ((makerTasks.trade_id.contract_type == 'A') && (outcome == 'Settle Trade')) {
                        makerTasks.value_date = valDate;
                    } else if ((makerTasks.trade_id.contract_type != 'A') && (outcome == 'Settle Trade')) {
                        makerTasks.value_date = "";
                    } else if (((makerTasks.trade_id.fx_location == 'L') || (makerTasks.trade_id.fx_location == 'O')) && (outcome == 'Process Trade Cancellation')) {
                        makerTasks.fxr_td = fxrTD;
                    } else if ((makerTasks.trade_id.fx_location != 'L') && (makerTasks.trade_id.fx_location != 'O') && (outcome == 'Process Trade Cancellation')) {
                        makerTasks.fxr_td = "";
                    }
                    makerTasks.settlement_date = settDate;
                    makerTasks.update();
                }
            }

            //update bulk record after all tasks are processed 
            var grbulk = new GlideRecord("x_hsb11_hsbc_mss_o_hsbc_bulk_transaction");
            grbulk.addQuery("sys_id", bulkid);
            grbulk.query();
            if (grbulk.next()) {
                if (grbulk.outcome == 'Review and closed the task') {
                    grbulk.bulk_task_type = 'GHSS Handler';
                } else {
                    grbulk.bulk_task_type = 'Checker';
                }
                grbulk.current_maker_assignee = assignedto;
                grbulk.maker_assignment_group = assignmentgroup;
                grbulk.new_maker_task_assignee = assignedto;
                grbulk.outcome = outcome;
                grbulk.advice = advice;
                grbulk.reason_code = reasoncode;
                grbulk.reason_description = reasondesc;
                grbulk.suspend = suspend;
                grbulk.cancel_by = cancelby;
                grbulk.settlement_type = setttype;
                grbulk.bk_to_bk_info = bktobkinfo;
                grbulk.cancellation_reference = cancreference;
                grbulk.collect_cancel_charge = cancelcharge;
                grbulk.assigned_to = '';
                grbulk.lock = false; //MSSCUSTODY-3993
                //adding as part of 4901
                grbulk.settlement_date = settDate;
                grbulk.fxr_td = fxrTD;
                grbulk.value_date = valDate;
                grbulk.comments = comments; // MSSCUSTODY-6379

                //MSSCUSTODY-6087
                grbulk.fx_cx = fxcx;
                grbulk.gdi = gdi;

                //MSSCUSTODY-7226
                grbulk.sub_outcome = subOutcome;
                grbulk.transaction_reference = transRef;
                grbulk.transaction_type_display = transType;
                grbulk.legacy_status_display = legStatus;
                grbulk.pair_switch_reference = switchRef;
                grbulk.amend_counterparty_code_ref = counterpartyCode;

                grbulk.update();
            }

            return true;

        } catch (ex) {
            gs.error('SI MSSCustodyBulkProcessUtils_workspace - Error while processing maker tasks, bulkID:' + bulkid + ',error:' + ex.message);
        }
    },


    updateMakerTaskbak: function(sysparm_bulkid, sysparm_assignmentgroup, sysparm_assignedto, sysparm_outcome, sysparm_advice, sysparm_reasoncode, sysparm_reasondescription, sysparm_suspend, sysparm_cancelby, sysparm_settlementtype, sysparm_bktobk, sysparm_cancellationreference, sysparm_collectcancelcharge, sysparm_settDate, sysparm_fxrTD, sysparm_valDate, sysparm_comments, sysparm_uploadType, sysparm_tasksCount, sysparm_fxcx, sysparm_gdi, sysparm_subOutcome, sysparm_transRef, sysparm_transType, sysparm_legStatus, sysparm_switchRef, sysparm_counterpartyCode) { //MSSCUSTODY-3396 //MSSOTIQUBE-2465

        try {
            /*var bulkid = this.getParameter('sysparm_bulkid');
            var assignmentgroup = this.getParameter('sysparm_assignmentgroup');
            var assignedto = this.getParameter('sysparm_assignedto');
            var outcome = this.getParameter('sysparm_outcome');
            var advice = this.getParameter('sysparm_advice');
            var reasoncode = this.getParameter('sysparm_reasoncode');
            var reasondesc = this.getParameter('sysparm_reasondescription');
            var suspend = this.getParameter('sysparm_suspend');
            var cancelby = this.getParameter('sysparm_cancelby');
            var setttype = this.getParameter('sysparm_settlementtype');
            var bktobkinfo = this.getParameter('sysparm_bktobk');
            var cancreference = this.getParameter('sysparm_cancellationreference');
            var cancelcharge = this.getParameter('sysparm_collectcancelcharge');
            //adding as part of 4901
            var settDate = this.getParameter('sysparm_settDate');
            var fxrTD = this.getParameter('sysparm_fxrTD');
            var valDate = this.getParameter('sysparm_valDate');
            var comments = this.getParameter('sysparm_comments'); // MSSCUSTODY-6379
            var uploadType = this.getParameter('sysparm_uploadType'); // MSSCUSTODY-6821 // 7191
            var tasksCount = this.getParameter('sysparm_tasksCount');

            //MSSCUSTODY-6087
            var fxcx = this.getParameter('sysparm_fxcx');
            var gdi = this.getParameter('sysparm_gdi');

            //MSSCUSTODY-7226
            var subOutcome = this.getParameter('sysparm_subOutcome');
            var transRef = this.getParameter('sysparm_transRef');
            var transType = this.getParameter('sysparm_transType');
            var legStatus = this.getParameter('sysparm_legStatus');
            var switchRef = this.getParameter('sysparm_switchRef');
            var counterpartyCode = this.getParameter('sysparm_counterpartyCode');
			*/

            var bulkid = sysparm_bulkid;
            var assignmentgroup = sysparm_assignmentgroup;
            var assignedto = sysparm_assignedto;
            var outcome = sysparm_outcome;
            var advice = sysparm_advice;
            var reasoncode = sysparm_reasoncode;
            var reasondesc = sysparm_reasondescription;
            var suspend = sysparm_suspend;
            var cancelby = sysparm_cancelby;
            var setttype = sysparm_settlementtype;
            var bktobkinfo = sysparm_bktobk;
            var cancreference = sysparm_cancellationreference;
            var cancelcharge = sysparm_collectcancelcharge;
            //adding as part of 4901
            var settDate = sysparm_settDate;
            var fxrTD = sysparm_fxrTD;
            var valDate = sysparm_valDate;
            var comments = sysparm_comments; // MSSCUSTODY-6379
            var uploadType = sysparm_uploadType; // MSSCUSTODY-6821 // 7191
            var tasksCount = sysparm_tasksCount;

            //MSSCUSTODY-6087
            var fxcx = sysparm_fxcx;
            var gdi = sysparm_gdi;

            //MSSCUSTODY-7226
            var subOutcome = sysparm_subOutcome;
            var transRef = sysparm_transRef;
            var transType = sysparm_transType;
            var legStatus = sysparm_legStatus;
            var switchRef = sysparm_switchRef;
            var counterpartyCode = sysparm_counterpartyCode;

            var threshold = gs.getProperty('x_hsb11_mss_c_proc.bulk_threshold_event_queue');

            var makerTasks = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            makerTasks.addEncodedQuery('active=true^trade_task_type=Maker^bulk_id=' + bulkid);
            makerTasks.query();


            if (parseInt(tasksCount, 10) > parseInt(threshold, 10) && gs.getProperty('x_hsb11_mss_c_proc.BulkEventQueue') == 'true') {

                var obj = {
                    bulkid: bulkid,
                    assignmentgroup: assignmentgroup,
                    assignedto: assignedto,
                    outcome: outcome,
                    advice: advice,
                    reasoncode: reasoncode,
                    reasondesc: reasondesc,
                    suspend: suspend,
                    cancelby: cancelby,
                    setttype: setttype,
                    bktobkinfo: bktobkinfo,
                    cancreference: cancreference,
                    cancelcharge: cancelcharge,
                    settDate: settDate,
                    fxrTD: fxrTD,
                    valDate: valDate,
                    comments: comments,
                    uploadType: uploadType,

                    //MSSCUSTODY-6087
                    fxcx: fxcx,
                    gdi: gdi,

                    //MSSCUSTODY-7266
                    subOutcome: subOutcome,
                    transRef: transRef,
                    transType: transType,
                    legStatus: legStatus,
                    switchRef: switchRef,
                    counterpartyCode: counterpartyCode

                };

                var bulkInfo = JSON.stringify(obj);

                //If number of Maker Task in the bulk is larger than threshold, use asyn event queue approach
                var makerArray = [];
                var j = 0;
                var makerTaskinSingleEvent = gs.getProperty('x_hsb11_mss_c_proc.number_of_items_in_bulk_event'); //number of trades to be processed via a single event for case creation
                while (makerTasks.next()) {
                    makerArray.push(makerTasks.sys_id.toString());
                    j++;

                    if (j == makerTaskinSingleEvent) {
                        gs.eventQueue("x_hsb11_mss_c_proc.cust_makertask_update", current, bulkInfo, makerArray.join(','));
                        //reset to initial
                        j = 0;
                        makerArray = [];
                    }
                }

                //create event for the remainings after loop completes
                if (j > 0) {
                    gs.eventQueue("x_hsb11_mss_c_proc.cust_makertask_update", current, bulkInfo, makerArray.join(','));
                }

                var evtName = "x_hsb11_mss_c_proc.cust_makertask_update";
                var evtComplete = false;
                var globalSleep = new global.MSSQuerySysEventQueue();

                //loop to check all events are completed, after which will update the bulk record and release the session, due to an issue on form loading if maker opens the bulk form after submit but task update are still not complted
                for (var i = 0; i < 50; i++) {
                    globalSleep.sleepUtility(5000);
                    evtComplete = new global.MSSQuerySysEventQueue().checkCustBulkEventState(evtName, bulkid);
                    if (evtComplete == true) {
                        break;
                    }
                }

            } else {

                while (makerTasks.next()) {
                    if (outcome == 'Review and closed the task') { // MSSCUSTODY-3964 - Cancelling associated flow if outcome is review and close the task for manual.
                        makerTasks.state = '3'; //closing related maker task
                        makerTasks.assignment_group = assignmentgroup; //Populating assignment group
                        makerTasks.assigned_to = assignedto; //Populating assigned to
                        makerTasks.outcome = outcome;
                        makerTasks.lock = false; //MSSCUSTODY-3993
                        makerTasks.update();
                        var grCusCase = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_case");
                        grCusCase.addEncodedQuery('sys_id=' + makerTasks.trade_case_id + '^bulk_id=' + bulkid);
                        grCusCase.query();
                        if (grCusCase.next()) {
                            grCusCase.state = '3';
                            grCusCase.update();
                        }

                        new x_hsb11_mss_c_proc.MSSCustodyBulkUtils().cancelFlow(makerTasks.trade_case_id, 'Cancelling flow as state is Review and Close');
                        makerTasks.work_notes = 'Cancelling flow as state is Review and Close'; // Updating work notes of Task
                    } else {

                        makerTasks.assignment_group = assignmentgroup; //Populating assignment group
                        makerTasks.assigned_to = assignedto; //Populating assigned to
                        makerTasks.outcome = outcome;
                        makerTasks.advice = advice;
                        if ((uploadType == '') || (uploadType == 'bulk_level')) {
                            makerTasks.reason_code = reasoncode;
                            makerTasks.reason_description = reasondesc;
                            makerTasks.cancellation_reference = cancreference;
                        }
                        makerTasks.suspend = suspend;
                        makerTasks.cancel_by = cancelby; // for outcome 'Process Trade Cancellation'
                        makerTasks.settlement_type = setttype; // for outcome 'Settle Trade'
                        makerTasks.bk_to_bk_info = bktobkinfo;
                        makerTasks.collect_cancel_charge = cancelcharge;
                        makerTasks.state = '3'; //closing related maker task
                        makerTasks.lock = false; //MSSCUSTODY-3993

                        // MSSCUSTODY-6379
                        makerTasks.work_notes = comments;

                        //MSSCUSTODY-6087
                        makerTasks.fx_cx = fxcx;
                        makerTasks.gdi_indicator = gdi;

                        //MSSCUSTODY-7266
                        makerTasks.bulk_id.sub_outcome = subOutcome;
                        makerTasks.bulk_id.transaction_reference = transRef;
                        makerTasks.bulk_id.transaction_type_display = transType;
                        makerTasks.bulk_id.legacy_status_display = legStatus;
                        makerTasks.bulk_id.pair_switch_reference = switchRef;
                        makerTasks.bulk_id.amend_counterparty_code_ref = counterpartyCode;

                        //added as part of 4901
                        if ((makerTasks.trade_id.contract_type == 'C') && (outcome == 'Confirm Trade')) {
                            makerTasks.value_date = valDate;
                        } else if ((makerTasks.trade_id.contract_type != 'C') && (outcome == 'Confirm Trade')) {
                            makerTasks.value_date = "";
                        } else if ((makerTasks.trade_id.contract_type == 'A') && (outcome == 'Settle Trade')) {
                            makerTasks.value_date = valDate;
                        } else if ((makerTasks.trade_id.contract_type != 'A') && (outcome == 'Settle Trade')) {
                            makerTasks.value_date = "";
                        } else if (((makerTasks.trade_id.fx_location == 'L') || (makerTasks.trade_id.fx_location == 'O')) && (outcome == 'Process Trade Cancellation')) {
                            makerTasks.fxr_td = fxrTD;
                        } else if ((makerTasks.trade_id.fx_location != 'L') && (makerTasks.trade_id.fx_location != 'O') && (outcome == 'Process Trade Cancellation')) {
                            makerTasks.fxr_td = "";
                        }
                        makerTasks.settlement_date = settDate;
                        makerTasks.update();
                    }
                }
            }

            //update bulk record after all tasks are processed 
            var grbulk = new GlideRecord("x_hsb11_hsbc_mss_o_hsbc_bulk_transaction");
            grbulk.addQuery("sys_id", bulkid);
            grbulk.query();
            if (grbulk.next()) {
                if (grbulk.outcome == 'Review and closed the task') {
                    grbulk.bulk_task_type = 'GHSS Handler';
                } else {
                    grbulk.bulk_task_type = 'Checker';
                }
                grbulk.current_maker_assignee = assignedto;
                grbulk.maker_assignment_group = assignmentgroup;
                grbulk.new_maker_task_assignee = assignedto;
                grbulk.outcome = outcome;
                grbulk.advice = advice;
                grbulk.reason_code = reasoncode;
                grbulk.reason_description = reasondesc;
                grbulk.suspend = suspend;
                grbulk.cancel_by = cancelby;
                grbulk.settlement_type = setttype;
                grbulk.bk_to_bk_info = bktobkinfo;
                grbulk.cancellation_reference = cancreference;
                grbulk.collect_cancel_charge = cancelcharge;
                grbulk.assigned_to = '';
                grbulk.lock = false; //MSSCUSTODY-3993
                //adding as part of 4901
                grbulk.settlement_date = settDate;
                grbulk.fxr_td = fxrTD;
                grbulk.value_date = valDate;
                grbulk.comments = comments; // MSSCUSTODY-6379

                //MSSCUSTODY-6087
                grbulk.fx_cx = fxcx;
                grbulk.gdi = gdi;

                //MSSCUSTODY-7226
                grbulk.sub_outcome = subOutcome;
                grbulk.transaction_reference = transRef;
                grbulk.transaction_type_display = transType;
                grbulk.legacy_status_display = legStatus;
                grbulk.pair_switch_reference = switchRef;
                grbulk.amend_counterparty_code_ref = counterpartyCode;

                grbulk.update();
            }

            return true;

        } catch (ex) {
            gs.error('SI MSSCustodyBulkProcessUtils_workspace - Error while processing maker tasks, bulkID:' + bulkid + ',error:' + ex.message);
        }
    },

    //MSSCUSTODY-7111
    getCheckerTasks: function(bulkId) {
        try {
            var bulkGR = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            if (!bulkGR.get(bulkId)) return 'Bulk record not found';

            var activeTradeCount = parseInt(bulkGR.active_trade_count, 10) || 0;
            var status = bulkGR.processing_status + '';
            var checkerCount = 0;
            var newStatus = '';

            // If linking is already completed, return status
            if (status.indexOf('Checker Tasks linking completed') !== -1) {
                return status;
            }

            // Count active Checker tasks in state 1 or 2 for this bulk
            var ga = new GlideAggregate('x_hsb11_mss_c_proc_mss_custody_task');
            ga.addEncodedQuery('bulk_id=' + bulkId + '^trade_task_type=Checker^active=true^stateIN1,2');
            ga.addAggregate('COUNT');
            ga.query();
            if (ga.next()) {
                checkerCount = ga.getAggregate('COUNT');
            }

            // Set new status based on count
            if (checkerCount == activeTradeCount) {
                newStatus = "Checker Tasks linking completed: " + checkerCount + " / " + activeTradeCount + " Tasks linked.";
            } else {
                newStatus = "Checker Tasks are in progress: " + checkerCount + " / " + activeTradeCount + " Tasks linked. Please refresh the page.";
            }

            // Only update if status has changed
            if (bulkGR.processing_status !== newStatus) {
                bulkGR.processing_status = newStatus;
                bulkGR.update();
            }
            return newStatus;
        } catch (e) {
            gs.info('Error in getCheckerTasks for processing status of bulk: ' + e.message);
            return '';
        }
    },
    //MSSCUSTODY-7111
    getGHSSHandlerTasks: function(bulkId) {
