            // Count active GHSS Handler tasks for this bulk
            var ga = new GlideAggregate('x_hsb11_mss_c_proc_mss_custody_task');
            ga.addEncodedQuery('bulk_id=' + bulkId + '^trade_task_type=GHSS Handler^active=true');
