    //MSSCUSTODY-7111
    getMakerTasks: function(bulkId) {
        try {
            var bulkGR = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            if (!bulkGR.get(bulkId)) return '';

            var makerCount = 0;
            var totalTrades = parseInt(bulkGR.active_trade_count, 10) || 0;
            var status = bulkGR.processing_status + '';
            var decisionReason = bulkGR.decision_reason.toString();
            var newStatus = '';

            // If decision reason exists, count rejected/automation failed tasks
            if (decisionReason != '') {
                var gr = new GlideAggregate('x_hsb11_mss_c_proc_mss_custody_task');
                gr.addEncodedQuery('active=true^trade_task_type=Maker^sub_trade_task_type=Checker-Rejected^bulk_id=' + bulkId);
                gr.addAggregate('COUNT');
                gr.query();
                if (gr.next()) {
                    makerCount = gr.getAggregate('COUNT');
                }
                newStatus = 'Maker Task linked for : ' + makerCount + ' rejected tasks.';
            } else if (status.indexOf('Maker Tasks linking completed') !== -1) {
                return status;
            } else {
                var ga = new GlideAggregate('x_hsb11_mss_c_proc_mss_custody_task');
                ga.addEncodedQuery('bulk_id=' + bulkId + '^trade_task_type=Maker^active=true^stateIN1,2');
                ga.addAggregate('COUNT');
                ga.query();
                if (ga.next()) {
                    makerCount = ga.getAggregate('COUNT');
                }
                if (makerCount == totalTrades) {
                    newStatus = 'Maker Tasks linking completed: ' + makerCount + ' / ' + totalTrades + ' Tasks linked.';
                } else {
                    newStatus = 'Maker Tasks are in progress: ' + makerCount + ' / ' + totalTrades + ' Tasks linked. Please refresh the page.';
                }
            }

            // Only update if status has changed
            if (bulkGR.processing_status !== newStatus) {
                bulkGR.processing_status = newStatus;
                bulkGR.update();
            }
            return newStatus;
        } catch (e) {
            gs.info('Error in getMakerTasks for processing status of bulk: ' + e.message);
            return '';
        }
    },

    //MSSCUSTODY-7111
    bulkProcess: function() {
        try {
            var bulkId = this.getParameter('sysparm_sys_id');
            var bulkGR = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            if (bulkGR.get(bulkId)) {
                var bulkTaskType = (bulkGR.bulk_task_type + '').trim();
                switch (bulkTaskType) {
                    case 'Maker':
                        return this.getMakerTasks(bulkId);
                    case 'Checker':
                        return this.getCheckerTasks(bulkId);
                    case 'GHSS Handler':
                        return this.getGHSSHandlerTasks(bulkId);
                }
                return '';
            }
        } catch (e) {
            gs.info('Error in bulkProcess for processing status of bulk: ' + e.message);
            return '';
        }
    },

