    //MSSOTIQUBE-2539 --> Optimized function to update cases and tasks in bulk as part of Performance optimization
    RemoveMakerTask: function() { //MSSCUSTODY-3546

        try {
            var bulkID = this.getParameter('sysparm_bulkID'); //get the passed bulk_id
            var taskID = this.getParameter('sysparm_taskID'); //get the passed array of sys_ids

            if (!taskID) {
                return;
            }

            var caseIds = []; // To store case IDs for tasks
            var tradeCaseId = "";

            var gCustodyTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task'); // Common GlideRecord object
            gCustodyTask.addEncodedQuery('sys_idIN' + taskID); // Query tasks with the provided sys_ids
            gCustodyTask.setLimit(1); // Only fetch one record
            gCustodyTask.query();

            //MSSOTIQUBE-2539 --> Fetching case type (Automated/Manual) only once
            var caseType = "";
            if (gCustodyTask.next()) {
                caseType = gCustodyTask.trade_id.case_type; // Fetch the case type directly
            }

            gCustodyTask.initialize();
            gCustodyTask.addEncodedQuery('sys_idIN' + taskID); // Query tasks again with the provided sys_ids
            gCustodyTask.query();

            while (gCustodyTask.next()) {
                tradeCaseId = gCustodyTask.getValue('trade_case_id'); // Fetch trade_case_id
                if (tradeCaseId)
                    caseIds.push(tradeCaseId); // Collect all case IDs
            }
            if (caseType == 'manual') {
                // ------Process Manual cases in bulk------
                var gCustodyManualCase = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_case');
                gCustodyManualCase.addQuery('sys_id', 'IN', caseIds.join(',')); // Query for manual cases
                // Set the values for the fields to be updated
                gCustodyManualCase.setValue('state', '3'); // Set state to 'closed'
                gCustodyManualCase.setValue('active', 'false'); // Mark case as inactive
                gCustodyManualCase.updateMultiple(); // Perform bulk update

                // ------Process Manual tasks in bulk------
                gCustodyTask.initialize(); // Reuse the common GlideRecord object
                gCustodyTask.addQuery('sys_idIN' + taskID); // Query for specific tasks
                // Set the values for the fields to be updated
                gCustodyTask.setValue('state', '7'); // Set state to 'closed'
                gCustodyTask.setValue('active', 'false'); // Mark task as inactive
                gCustodyTask.setValue('lock', false); // Unlock the task
                gCustodyTask.assigned_to = 'NULL'; // Clear assigned user
                gCustodyTask.assignment_group = 'NULL'; // Clear assignment group
                // Perform the bulk update
                gCustodyTask.updateMultiple();

            } else if (caseType == 'automated') {
                // ------Process Automated cases in bulk------
                var gCustodyAutomatedCase = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_case');
                gCustodyAutomatedCase.addQuery('sys_id', 'IN', caseIds.join(',')); // Query for automated cases
                gCustodyAutomatedCase.setValue('bulk_id', ''); // Clear the bulk ID
                gCustodyAutomatedCase.updateMultiple(); // Perform bulk update

                // ------Process Automated Tasks in bulk------
                gCustodyTask.initialize(); // Reuse the common GlideRecord object
                gCustodyTask.addQuery('sys_idIN' + taskID); // Query for specific tasks
                // Set the values for the fields to be updated
                gCustodyTask.setValue('bulk_id', ''); // Clear the bulk ID
                gCustodyTask.setValue('state', '1');
                gCustodyTask.setValue('lock', false); // Unlock the task
                gCustodyTask.assigned_to = 'NULL'; // Clear assigned user
                gCustodyTask.assignment_group = 'NULL'; // Clear assignment group
                // Perform the bulk update
                gCustodyTask.updateMultiple();

            }

            // Update active trade count for the bulk ID and Close bulk transaction
            if (bulkID) {
                var activeTaskCount = new GlideAggregate('x_hsb11_mss_c_proc_mss_custody_task');
                activeTaskCount.addQuery('bulk_id', bulkID); // Filter tasks by bulk ID
                activeTaskCount.addQuery('active', true); // Filter only active tasks
                activeTaskCount.addAggregate('COUNT'); // Count the number of active tasks
                activeTaskCount.query();
                if (activeTaskCount.next()) {
                    var count = parseInt(activeTaskCount.getAggregate('COUNT'), 10); // Get the count of active tasks
                    // Update the trade count in the bulk transaction
                    var gBulk = new GlideRecord("x_hsb11_hsbc_mss_o_hsbc_bulk_transaction");
                    if (gBulk.get(bulkID)) {
                        gBulk.setValue('active_trade_count', count); // Update the active trade count
                        if (count === 0) {
                            gBulk.setValue('state', '7'); // Set state to 'Cancelled' if no active tasks remain
                        }
                        gBulk.update(); // Save the changes
                    }
                }
            }
        } catch (error) {
            gs.error("SI MSSCustodyBulkProcessUtils_workspace - Error in RemoveMakerTask: " + error.message);
        }
    },
    type: 'MSSCustodyBulkProcessUtils_workspace'
};
